-- Structural facts and source snapshots; actual performance remains independent.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('groups_a')::uuid),(md5('groups_b')::uuid);
insert into profiles(id,display_name) values(md5('groups_a')::uuid,'Group A'),(md5('groups_b')::uuid,'Group B');
insert into account_preferences(owner_id,scheduling_timezone) values(md5('groups_a')::uuid,'UTC'),(md5('groups_b')::uuid,'UTC');
select set_config('request.jwt.claims',json_build_object('sub',md5('groups_a')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select set_config('g.w',start_ad_hoc_workout()::text,true);
select set_config('g.a',edit_workout(current_setting('g.w')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select set_config('g.b',edit_workout(current_setting('g.w')::uuid,'add',(select id from exercises where slug='standing_dumbbell_curl'))::text,true);
select set_config('g.c',edit_workout(current_setting('g.w')::uuid,'add',(select id from exercises where slug='rope_triceps_pushdown'))::text,true);
select set_config('g.members',jsonb_build_array(jsonb_build_object('type','selection','id',current_setting('g.a')),jsonb_build_object('type','selection','id',current_setting('g.b')))::text,true);
select set_config('g.group',gen_random_uuid()::text,true);
select set_config('g.request',gen_random_uuid()::text,true);
select set_config('g.set',(select id::text from workout_sets where workout_exercise_id=current_setting('g.a')::uuid order by position limit 1),true);
select lives_ok($$select log_workout_set(p_item=>current_setting('g.a')::uuid,p_id=>current_setting('g.set')::uuid,p_operation=>'save',p_revision=>0,p_mutation=>gen_random_uuid(),p_reps=>8,p_weight=>50,p_completed=>true)$$,'real actual set recorded before grouping');
select set_config('g.actuals',(select jsonb_agg(to_jsonb(s) order by s.id)::text from workout_sets s where owner_id=auth.uid()),true);
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'create',0,current_setting('g.members')::jsonb,current_setting('g.request')::uuid)$$,'create two-member group');
select is(jsonb_array_length(workout_groups(current_setting('g.w')::uuid)),1,'one structural group');
select is((workout_groups(current_setting('g.w')::uuid)->0->>'revision')::int,1,'server revision starts at one');
select is(workout_groups(current_setting('g.w')::uuid)->0->'members',current_setting('g.members')::jsonb,'exact ordered selection IDs retained');
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'create',0,current_setting('g.members')::jsonb,current_setting('g.request')::uuid)$$,'same request returns existing successful result');
select is((select count(*)::int from workout_group_commands where workout_session_id=current_setting('g.w')::uuid),1,'retry creates no duplicate fact');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'ungroup',1,'[]',current_setting('g.request')::uuid)$$,'23514',null,'same UUID cannot mean another intent');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,current_setting('g.members')::jsonb,gen_random_uuid())$$,'23514',null,'overlapping groups rejected');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,jsonb_build_array(current_setting('g.members')::jsonb->0),gen_random_uuid())$$,'22023',null,'one member rejected');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,jsonb_build_array(current_setting('g.members')::jsonb->0,current_setting('g.members')::jsonb->0),gen_random_uuid())$$,'22023',null,'duplicate identity rejected');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,current_setting('g.members')::jsonb||current_setting('g.members')::jsonb,gen_random_uuid())$$,'22023',null,'four members rejected');
select throws_ok($$select edit_workout(current_setting('g.w')::uuid,'remove',null,current_setting('g.b')::uuid)$$,'23514',null,'removal cannot leave a stale one-member group');
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'edit',1,current_setting('g.members')::jsonb||jsonb_build_array(jsonb_build_object('type','selection','id',current_setting('g.c'))),gen_random_uuid())$$,'third member added atomically');
select is(jsonb_array_length(workout_groups(current_setting('g.w')::uuid)->0->'members'),3,'three real members');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'edit',1,current_setting('g.members')::jsonb,gen_random_uuid())$$,'40001',null,'stale revision cannot overwrite third member');
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'edit',2,jsonb_build_array(current_setting('g.members')::jsonb->1,current_setting('g.members')::jsonb->0),gen_random_uuid())$$,'member removal and reorder preserve group identity');
select is(workout_groups(current_setting('g.w')::uuid)->0->>'id',current_setting('g.group'),'edit retains group UUID');
select is((select jsonb_agg(to_jsonb(s) order by s.id)::text from workout_sets s where owner_id=auth.uid()),current_setting('g.actuals'),'group create/edit/reorder leave actuals, revisions, ordering and effort byte-identical');
select throws_ok($$update workout_group_commands set members='[]'::jsonb$$,'42501',null,'historical command facts cannot be edited');
select throws_ok($$delete from workout_group_commands$$,'42501',null,'historical command facts cannot be deleted directly');
select throws_ok($$insert into workout_group_commands(request_id,workout_session_id,group_id,operation,expected_revision,members,revision) values(gen_random_uuid(),current_setting('g.w')::uuid,gen_random_uuid(),'create',0,'[]',99)$$,'42501',null,'derived revisions cannot be supplied');
select set_config('request.jwt.claims',json_build_object('sub',md5('groups_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_group_commands),0,'foreign structural history hidden by RLS');
select throws_ok($$select workout_groups(current_setting('g.w')::uuid)$$,'42501',null,'foreign workout schedule/group read rejected');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'ungroup',3,'[]',gen_random_uuid())$$,'42501',null,'foreign group edit denied');
select set_config('g.foreign',start_ad_hoc_workout()::text,true);
select set_config('g.foreignitem',edit_workout(current_setting('g.foreign')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select set_config('request.jwt.claims',json_build_object('sub',md5('groups_a')::uuid,'role','authenticated')::text,true);
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,jsonb_build_array(jsonb_build_object('type','selection','id',current_setting('g.c')),jsonb_build_object('type','selection','id',current_setting('g.foreignitem'))),gen_random_uuid())$$,'42501',null,'cross-owner member rejected');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,jsonb_build_array(jsonb_build_object('type','movement','id',gen_random_uuid()),jsonb_build_object('type','selection','id',current_setting('g.c'))),gen_random_uuid())$$,'42501',null,'forged movement/program slot cannot become a member');
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,current_setting('g.group')::uuid,'ungroup',3,'[]',gen_random_uuid())$$,'ungroup is atomic');
select is(jsonb_array_length(workout_groups(current_setting('g.w')::uuid)),0,'ungroup leaves no one-member structure');
select is((select jsonb_agg(to_jsonb(s) order by s.id)::text from workout_sets s where owner_id=auth.uid()),current_setting('g.actuals'),'ungroup retains every original actual set');
select is((workout_group_layout(current_setting('g.w')::uuid)->>'hasHistory')::boolean,true,'final empty grouping retains structural provenance');
select lives_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,current_setting('g.members')::jsonb,gen_random_uuid())$$,'a new independent group can be created after ungrouping');
select lives_ok($$select end_workout(current_setting('g.w')::uuid,'completed')$$,'ordinary closure still uses actual evidence');
select throws_ok($$select change_workout_group(current_setting('g.w')::uuid,gen_random_uuid(),'create',0,current_setting('g.members')::jsonb,gen_random_uuid())$$,'23514',null,'closed workout rejects new group edits');
select is(jsonb_array_length(workout_groups(current_setting('g.w')::uuid)),1,'closed history retains final group');
select set_config('g.favorite',save_favorite_workout('completed_ad_hoc',current_setting('g.w')::uuid,null,'Grouped shortcut',gen_random_uuid())::text,true);
-- Only one eligible member means no fictional two-member Favorite group.
select is((select count(*)::int from favorite_workouts f cross join lateral jsonb_array_elements(f.definition)s where f.id=current_setting('g.favorite')::uuid and s ? 'group'),0,'ineligible members never manufacture a reusable Superset');
select lives_ok($$select retain_workout(current_setting('g.w')::uuid,'archive',gen_random_uuid(),0)$$,'archive keeps closed structural history');
select is(jsonb_array_length(workout_groups(current_setting('g.w')::uuid)),1,'archived grouping remains owner readable');
select lives_ok($$select retain_workout(current_setting('g.w')::uuid,'restore',gen_random_uuid(),1)$$,'restore retains structure without replaying group commands');
select lives_ok($$select retain_workout(current_setting('g.w')::uuid,'delete',gen_random_uuid(),2)$$,'permanent deletion cleans structural references through parent ownership');
select is((select count(*)::int from workout_group_commands where workout_session_id=current_setting('g.w')::uuid),0,'deleted workout retains no orphan group data');
select ok((select definition is not null from favorite_workouts where id=current_setting('g.favorite')::uuid),'Favorite structure remains valid after source deletion');

-- Both seeded immutable versions instantiate real unselected movement groups.
create function pg_temp.seed_groups(slug text) returns setof text language plpgsql security invoker set search_path=public,extensions,pg_temp as $$
declare version_id uuid;assignment uuid;w uuid;group_id uuid;before_sets jsonb;m public.workout_movements;e uuid;recorded_set public.workout_sets;fav uuid;launched uuid;
begin
 select v.id into version_id from program_versions v where v.definition->'program'->>'slug'=slug;
 return next ok(version_id is not null,'seed version exists: '||slug);
 select id into assignment from program_assignments where owner_id=auth.uid() and state='active';
 if assignment is not null then perform program_lifecycle('end_now',gen_random_uuid(),assignment,(select lifecycle_revision from program_assignments where id=assignment));end if;
 assignment:=(program_lifecycle('start',gen_random_uuid(),null,0,version_id,current_date,'UTC')->>'assignmentId')::uuid;
 w:=start_program_workout(version_id,1,gen_random_uuid());
 return next is(jsonb_array_length(workout_groups(w)),2,'first seeded workout contains two real groups');
 return next is((select count(*)::int from workout_exercises where workout_session_id=w),0,'group instantiation does not select exercises or create performance');
 return next ok(not exists(select 1 from jsonb_array_elements(workout_groups(w))g where g->>'sourceGroupId' is null),'prescribed group source IDs are proven');
 for m in select * from workout_movements where workout_session_id=w and owner_id=auth.uid() order by position loop
  e:=select_program_exercise(m.id,(m.slot_snapshot->>'exercise_id')::uuid,null,gen_random_uuid());
  for recorded_set in select * from workout_sets where workout_exercise_id=e order by position loop
   perform log_workout_set(p_item=>e,p_id=>recorded_set.id,p_operation=>'save',p_revision=>recorded_set.revision,p_mutation=>gen_random_uuid(),p_reps=>10,p_weight=>case when recorded_set.load_mode='bodyweight' then null else 50 end,p_mode=>recorded_set.load_mode,p_completed=>true);
  end loop;
 end loop;
 group_id:=(workout_groups(w)->0->>'id')::uuid;
 select x.id into e from workout_movements x where x.workout_session_id=w and not exists(select 1 from jsonb_array_elements(workout_groups(w))g cross join lateral jsonb_array_elements(g->'members')member where member->>'id'=x.id::text) order by x.position limit 1;
 perform change_workout_group(w,group_id,'edit',1,(workout_groups(w)->0->'members')||jsonb_build_array(jsonb_build_object('type','movement','id',e)),gen_random_uuid());
 return next is((select jsonb_array_length(g->'members') from jsonb_array_elements(workout_groups(w))g where g->>'id'=group_id::text),3,'a recorded program can add a third member without changing source slots');
 perform end_workout(w,'completed');
 return next is((select completion_status from workout_sessions where id=w),'full','qualifying program completion uses real prescribed work');
 fav:=save_favorite_workout('completed_workout',w,null,'Actual grouped program workout',gen_random_uuid());
 return next is((select count(distinct x.value->'group'->>'key')::int from favorite_workouts f cross join lateral jsonb_array_elements(f.definition)x where f.id=fav),2,'Favorite snapshots preserve both final groups');
 launched:=start_favorite_workout(fav,gen_random_uuid());
 return next is(jsonb_array_length(workout_groups(launched)),2,'Favorite launch remaps both groups through the same engine');
 return next ok(exists(select 1 from jsonb_array_elements(workout_groups(launched))g where jsonb_array_length(g->'members')=3),'three-member final structure survives Favorite remapping');
 return next ok((select program_assignment_id is null and source_program_version_id is null from workout_sessions where id=launched),'grouped Favorite is independent of program');
 return next is((select count(*)::int from workout_sets s join workout_exercises e on e.id=s.workout_exercise_id where e.workout_session_id=launched and s.status='completed'),0,'Favorite never copies completed actuals');
 return next is((workout_group_layout(launched)->>'favoriteEdited')::boolean,false,'unmodified Favorite grouping retains source attribution');
 return next ok(not exists(select 1 from jsonb_array_elements(workout_groups(launched))g where g->>'sourceGroupId' is null),'Favorite source group identities are validated');
 group_id:=(workout_groups(launched)->0->>'id')::uuid;
 perform change_workout_group(launched,group_id,'ungroup',1,'[]',gen_random_uuid());
 return next is((workout_group_layout(launched)->>'favoriteEdited')::boolean,true,'editing a Favorite grouping is distinct from the immutable template');
 return next is((select count(distinct x.value->'group'->>'key')::int from favorite_workouts f cross join lateral jsonb_array_elements(f.definition)x where f.id=fav),2,'local ungroup cannot alter original Favorite snapshot');
 perform end_workout(launched,'abandoned');
end $$;
select * from pg_temp.seed_groups('upper-lower-superset-split');
select * from pg_temp.seed_groups('full-body-superset-training');
select set_config('g.copy',clone_program((select id from program_versions where definition->'program'->>'slug'='full-body-superset-training'),'Private grouped copy',gen_random_uuid())::text,true);
select is((select count(*)::int from program_day_groups g join program_days d on d.id=g.program_day_id where d.program_id=current_setting('g.copy')::uuid),6,'cloning remaps all source groups into owned draft slots');
select throws_ok($$delete from program_slots where id=(select g.members[1] from program_day_groups g join program_days d on d.id=g.program_day_id where d.program_id=current_setting('g.copy')::uuid limit 1)$$,'23514',null,'grouped draft slots require explicit ungroup before removal');
select set_config('g.version',snapshot_program(current_setting('g.copy')::uuid)::text,true);
select set_config('g.definition',(select definition::text from program_versions where id=current_setting('g.version')::uuid),true);
update program_day_groups set members=array[members[2],members[1]] where id=(select g.id from program_day_groups g join program_days d on d.id=g.program_day_id where d.program_id=current_setting('g.copy')::uuid limit 1);
select is((select definition::text from program_versions where id=current_setting('g.version')::uuid),current_setting('g.definition'),'mutable draft group edits cannot rewrite an existing immutable version');
select isnt(snapshot_program(current_setting('g.copy')::uuid),current_setting('g.version')::uuid,'a revised grouping receives a distinct immutable version');

select set_config('request.jwt.claims',json_build_object('sub',md5('groups_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from program_day_groups),0,'another owner cannot read private template group definitions');
select is((select count(*)::int from program_versions where id=current_setting('g.version')::uuid),0,'foreign private immutable source version remains hidden');
select throws_ok($$insert into program_day_groups(program_day_id,members) values((current_setting('g.definition')::jsonb->'days'->0->>'id')::uuid,array[(current_setting('g.definition')::jsonb->'days'->0->'slots'->0->>'id')::uuid,(current_setting('g.definition')::jsonb->'days'->0->'slots'->1->>'id')::uuid])$$,'22023',null,'foreign day/slot UUIDs cannot become owned group authority');
with removed as(delete from program_day_groups returning id) select is((select count(*)::int from removed),0,'cross-owner template deletion affects no rows');
with updated as(update program_day_groups set members=members returning id) select is((select count(*)::int from updated),0,'cross-owner template update affects no rows');

reset role;
select lives_ok($$select body_private.install_body_superset_catalog()$$,'new Superset seed installer is repeatable without rewriting snapshots');
select is((select count(*)::int from program_versions where definition->'program'->>'slug' in('upper-lower-superset-split','full-body-superset-training')),2,'repeated seed installation creates no extra versions');
select ok(not has_table_privilege(r,t,'UPDATE') and not has_table_privilege(r,t,'DELETE'),t||': no mutable command history for '||r) from unnest(array['anon','authenticated','service_role'])r cross join unnest(array['public.workout_group_commands'])t;
select ok(not has_table_privilege(r,'public.program_day_groups','SELECT,INSERT,UPDATE,DELETE'),'template groups have no anonymous/service access: '||r) from unnest(array['anon','service_role'])r;
select ok(not has_function_privilege(r,f,'EXECUTE'),'no anonymous/service grouping RPC: '||f) from unnest(array['anon','service_role'])r cross join unnest(array['public.workout_groups(uuid)','public.workout_group_layout(uuid)','public.change_workout_group(uuid,uuid,text,bigint,jsonb,uuid)'])f;
select * from finish();
rollback;
